from llm_saea import Plan, benchmark, optimize

PLAN = Plan.from_dict({'surrogate': 'auto', 'operator': 'current_to_best', 'mutation': 0.55, 'crossover': 0.8, 'exploration': 0.45, 'local_fraction': 0.35, 'radius': 0.12, 'population': 30, 'generations': 6, 'reason': 'Only 24/100 evaluations used but stagnation is high (20) with zero recent improvement, indicating the current reference design is exploiting too narrowly. Auto surrogate lets held-out RMSE pick RBF vs quadratic for a 5D problem with limited data. Keep current_to_best (good balance of convergence and diversity), but modestly lower mutation/crossover toward robust exploration and raise exploration to 0.45 so the novelty-distance term pushes candidates away from repeatedly sampled regions; local fraction stays moderate (0.35) to retain local refinement within the 0.12 normalized radius. Population 30 with 6 generations balances surrogate retraining cost under the fixed budget without requesting extra true evaluations.'})

def solve(problem, budget=100, seed=0):
    return optimize(problem, budget=budget, seed=seed, method='saea', plan=PLAN)

if __name__ == '__main__':
    result = solve(benchmark('sphere', 5))
    print({'best_y': result.best_y, 'best_x': result.best_x.tolist()})
